// 通話状態
export type CallStatus = 'idle' | 'connecting' | 'connected' | 'disconnected' | 'error'

// 文字起こしメッセージ
export interface TranscriptMessage {
  role: 'user' | 'assistant'
  content: string
  timestamp: string // ISO 8601
}

// ConversationRelay WebSocket受信メッセージ
export interface SetupMessage {
  type: 'setup'
  callSid: string
  from: string
  to: string
  customParameters: Record<string, string>
}

export interface PromptMessage {
  type: 'prompt'
  voicePrompt: string
  lang: string
  last: boolean
}

export interface InterruptMessage {
  type: 'interrupt'
}

export interface DtmfMessage {
  type: 'dtmf'
  digit: string
}

export type ConversationRelayMessage =
  | SetupMessage
  | PromptMessage
  | InterruptMessage
  | DtmfMessage

// ConversationRelay送信メッセージ
export interface TextResponse {
  type: 'text'
  token: string
  last: boolean
}

export interface EndResponse {
  type: 'end'
}

// OpenAI会話履歴
export interface ConversationMessage {
  role: 'user' | 'assistant'
  content: string
}

// WebSocketセッション
export interface Session {
  callSid: string
  conversationHistory: ConversationMessage[]
  systemPrompt: string
}

// APIレスポンス
export interface ApiResponse<T> {
  success: boolean
  data?: T
  error?: string
}

