export const TWILIO_API_KEY = requireEnv('TWILIO_API_KEY')
export const TWILIO_API_SECRET = requireEnv('TWILIO_API_SECRET')
export const TWILIO_SYNC_SERVICE_SID = requireEnv('TWILIO_SYNC_SERVICE_SID')
export const TWILIO_TWIML_APP_SID = requireEnv('TWILIO_TWIML_APP_SID')

// Twilio RESTクライアント
