'use client'

import { useState, useEffect, useCallback } from 'react'

export function PromptEditor() {
  const [prompt, setPrompt] = useState('')
  const [isSaving, setIsSaving] = useState(false)
  const [savedMessage, setSavedMessage] = useState<string | null>(null)

  // 初期値ロード
  useEffect(() => {
    async function loadPrompt() {
      try {
        const response = await fetch('/api/prompt')
        const result = await response.json()
        if (result.success) {
          setPrompt(result.data.prompt)
        }
      } catch (error) {
        console.error('プロンプトの読み込みに失敗:', error)
      }
    }
    loadPrompt()
  }, [])

  // 保存
  const handleSave = useCallback(async () => {
    if (isSaving || prompt.trim().length === 0) return

    setIsSaving(true)
    setSavedMessage(null)

    try {
      const response = await fetch('/api/prompt', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: prompt.trim() }),
      })
      const result = await response.json()

      if (result.success) {
        setSavedMessage('保存しました')
        // 3秒後にメッセージを消す
        setTimeout(() => setSavedMessage(null), 3000)
      } else {
        throw new Error(result.error || '保存に失敗しました')
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : '保存に失敗しました'
      setSavedMessage(message)
      setTimeout(() => setSavedMessage(null), 5000)
    } finally {
      setIsSaving(false)
    }
  }, [isSaving, prompt])

  return (
    <section className="space-y-3">
      <h2 className="text-lg font-semibold text-gray-800">
        AIプロンプト設定
      </h2>

      <textarea
        value={prompt}
        onChange={(e) => setPrompt(e.target.value)}
        placeholder="AIが応対する内容を入力してください..."
        className="w-full min-h-32 resize-y rounded-lg border border-gray-300 p-3 text-sm
                   focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
        rows={5}
      />

      <div className="flex items-center gap-3">
        <button
          onClick={handleSave}
          disabled={isSaving || prompt.trim().length === 0}
          className={`
            rounded-lg px-4 py-2 text-sm font-medium text-white transition-colors
            ${isSaving || prompt.trim().length === 0
              ? 'bg-gray-300 cursor-not-allowed'
              : 'bg-blue-500 hover:bg-blue-600 active:bg-blue-700'}
          `}
        >
          {isSaving ? '保存中...' : '保存'}
        </button>

        {savedMessage && (
          <span className="text-sm text-green-600">{savedMessage}</span>
        )}
      </div>
    </section>
  )
}

