'use client'

import { useState, useEffect, useRef } from 'react'
import { SyncClient } from 'twilio-sync'

interface UseTwilioSyncReturn {
  syncClient: SyncClient | null
  isReady: boolean
}

export function useTwilioSync(): UseTwilioSyncReturn {
  const [syncClient, setSyncClient] = useState<SyncClient | null>(null)
  const [isReady, setIsReady] = useState(false)
  const clientRef = useRef<SyncClient | null>(null)

  useEffect(() => {
    async function initSync() {
      try {
        const response = await fetch('/api/sync-token')
        const result = await response.json()

        if (!result.success) {
          throw new Error(result.error || 'Syncトークン取得に失敗しました')
        }

        const client = new SyncClient(result.data.token)

        client.on('connectionStateChanged', (state: string) => {
          setIsReady(state === 'connected')
        })

        clientRef.current = client
        setSyncClient(client)
      } catch (error) {
        console.error('Sync Client初期化に失敗:', error)
      }
    }

    initSync()

    return () => {
      if (clientRef.current) {
        clientRef.current.shutdown()
        clientRef.current = null
      }
    }
  }, [])

  return { syncClient, isReady }
}

