'use client'

import { useState, useCallback, useRef } from 'react'
import type { SyncClient } from 'twilio-sync'
import type { TranscriptMessage } from '@/types'

interface UseTranscriptReturn {
  messages: TranscriptMessage[]
  subscribeToCall: (callSid: string) => void
  clear: () => void
}

export function useTranscript(
  syncClient: SyncClient | null
): UseTranscriptReturn {
  const [messages, setMessages] = useState<TranscriptMessage[]>([])
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const listRef = useRef<any>(null)

  // 現在のサブスクリプションを解除
  const unsubscribe = useCallback(() => {
    if (listRef.current) {
      listRef.current.removeAllListeners()
      listRef.current.close()
      listRef.current = null
    }
  }, [])

  // Sync Listをサブスクライブ
  const subscribeToCall = useCallback(
    async (callSid: string) => {
      if (!syncClient) return

      // 既存のサブスクリプションを解除
      unsubscribe()
      setMessages([])

      try {
        const list = await syncClient.list(`transcript-${callSid}`)
        listRef.current = list

        // 既存アイテムの読み込み（再接続時対応）
        const page = await list.getItems()
        if (page.items.length > 0) {
          const existingMessages: TranscriptMessage[] = page.items.map(
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (item: any) => item.data as TranscriptMessage
          )
          setMessages(existingMessages)
        }

        // リアルタイム更新の監視
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        list.on('itemAdded', (event: any) => {
          const newMessage = event.item.data as TranscriptMessage
          setMessages((prev) => [...prev, newMessage])
        })
      } catch (error) {
        console.error('Sync Listサブスクリプションエラー:', error)
      }
    },
    [syncClient, unsubscribe]
  )

  // メッセージクリア
  const clear = useCallback(() => {
    unsubscribe()
    setMessages([])
  }, [unsubscribe])

  return { messages, subscribeToCall, clear }
}

