import twilio from 'twilio'

// 環境変数の検証
function requireEnv(name: string): string {
  const value = process.env[name]
  if (!value) {
    throw new Error(`環境変数 ${name} が設定されていません`)
  }
  return value
}

export const TWILIO_ACCOUNT_SID = requireEnv('TWILIO_ACCOUNT_SID')
export const TWILIO_AUTH_TOKEN = requireEnv('TWILIO_AUTH_TOKEN')
export const TWILIO_API_KEY = requireEnv('TWILIO_API_KEY')
export const TWILIO_API_SECRET = requireEnv('TWILIO_API_SECRET')
export const TWILIO_SYNC_SERVICE_SID = requireEnv('TWILIO_SYNC_SERVICE_SID')
export const TWILIO_TWIML_APP_SID = requireEnv('TWILIO_TWIML_APP_SID')

// Twilio RESTクライアント
export const twilioClient = twilio(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)

// Syncサービスへのショートカット
export const syncService = twilioClient.sync.v1.services(TWILIO_SYNC_SERVICE_SID)

import OpenAI from 'openai'
import type { ConversationMessage } from '@/types'

// 環境変数の検証
const apiKey = process.env.OPENAI_API_KEY
if (!apiKey) {
  throw new Error('環境変数 OPENAI_API_KEY が設定されていません')
}

// OpenAIクライアント
export const openaiClient = new OpenAI({ apiKey })

// ベースシステムプロンプト（固定部分）
export const BASE_SYSTEM_PROMPT = `あなたは電話応対AIアシスタントです。以下のルールに従って応答してください。

【応答ルール】
- 1回の応答は1〜2文（50文字以内目安）で簡潔に答える
- 書き言葉ではなく、話し言葉（口語）で返答する
- 丁寧な敬語（です/ます調）を使用する
- 「はい」「承知しました」「かしこまりました」など適切に相槌を入れる
- 重要な情報（日時、人数、名前など）は必ず復唱して確認する
- 一度に複数の質問をしない。1つずつ確認する
- 電話番号、住所など長い情報は区切って伝える
- わからないことは正直に「確認いたします」と伝える

【禁止事項】
- マークダウン記法やリスト形式で話さない
- URLやメールアドレスを読み上げない
- 長い説明を一度に話さない`

// エラー時のフォールバック応答
export const FALLBACK_RESPONSES = {
  timeout: 'すみません、少しお時間いただいてもよろしいでしょうか。',
  rateLimit: '申し訳ございません、ただいま混み合っております。少々お待ちください。',
  general: '申し訳ございません、うまく聞き取れませんでした。もう一度おっしゃっていただけますか？',
} as const

// 会話履歴のトリミング（最大20往復 = 40メッセージ）
export function trimHistory(
  history: readonly ConversationMessage[],
  maxPairs: number = 20
): ConversationMessage[] {
  const maxMessages = maxPairs * 2
  if (history.length > maxMessages) {
    return history.slice(-maxMessages)
  }
  return [...history]
}

