export function getTwilioClient() {
  if (!_twilioClient) {
    _twilioClient = twilio(getEnv('TWILIO_ACCOUNT_SID'), getEnv('TWILIO_AUTH_TOKEN'))
  }
  return _twilioClient
}

export function getSyncService() {
  if (!_syncService) {
    const client = getTwilioClient()
    _syncService = client.sync.v1.services(getEnv('TWILIO_SYNC_SERVICE_SID'))
  }
  return _syncService
