    return Response.json(
      { success: false, error: message },
      { status: 500 }
    )
  }
}

import type WebSocket from 'ws'
import { syncService } from './twilio'
import { openaiClient, BASE_SYSTEM_PROMPT, FALLBACK_RESPONSES, trimHistory } from './openai'
import { getPrompt } from './prompt-store'
import type {
  Session,
  ConversationRelayMessage,
  SetupMessage,
  PromptMessage,
  ConversationMessage,
} from '../types'

// Sync Listにトランスクリプトアイテムを追加
async function addTranscriptItem(
  callSid: string,
  role: 'user' | 'assistant',
  content: string
): Promise<void> {
  try {
    await syncService
      .syncLists(`transcript-${callSid}`)
      .syncListItems.create({
        data: {
          role,
          content,
          timestamp: new Date().toISOString(),
        },
      })
  } catch (error) {
    console.error('Sync書き込みエラー:', error)
  }
}

// setup メッセージ処理
async function handleSetup(
  session: Session,
  data: SetupMessage
): Promise<Session> {
  const userPrompt = getPrompt()
  const systemPrompt = `${BASE_SYSTEM_PROMPT}\n\n【応対内容】\n${userPrompt}`

  // Sync List作成（TTL: 1時間）
  try {
    await syncService.syncLists.create({
      uniqueName: `transcript-${data.callSid}`,
      ttl: 3600,
    })
  } catch (error) {
    console.error('Sync List作成エラー:', error)
  }

  return {
    callSid: data.callSid,
    conversationHistory: [],
    systemPrompt,
  }
}

// prompt メッセージ処理
async function handlePrompt(
  ws: WebSocket,
  session: Session,
  data: PromptMessage
): Promise<Session> {
  const userText = data.voicePrompt

  // ユーザー発話をSyncに書き込み
  await addTranscriptItem(session.callSid, 'user', userText)

  // 会話履歴を更新（イミュータブル）
  const updatedHistory: ConversationMessage[] = [
    ...session.conversationHistory,
    { role: 'user', content: userText },
  ]
  const trimmedHistory = trimHistory(updatedHistory)

  let aiText: string

  try {
    // OpenAI API呼び出し
    const response = await openaiClient.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        { role: 'system', content: session.systemPrompt },
        ...trimmedHistory,
      ],
      max_tokens: 150,
      temperature: 0.7,
      presence_penalty: 0.1,
    })

    aiText = response.choices[0]?.message?.content ?? FALLBACK_RESPONSES.general
  } catch (error) {
    console.error('OpenAI APIエラー:', error)

    // エラーの種類に応じたフォールバック
    if (error instanceof Error) {
      if (error.message.includes('429') || error.message.includes('rate')) {
        aiText = FALLBACK_RESPONSES.rateLimit
      } else if (error.message.includes('timeout') || error.message.includes('504')) {
        aiText = FALLBACK_RESPONSES.timeout
      } else {
        aiText = FALLBACK_RESPONSES.general
      }
    } else {
      aiText = FALLBACK_RESPONSES.general
    }
  }

  // AI応答をWebSocketに送信
  const responseMessage = JSON.stringify({
    type: 'text',
    token: aiText,
    last: true,
  })
  ws.send(responseMessage)

  // AI応答をSyncに書き込み
  await addTranscriptItem(session.callSid, 'assistant', aiText)

  // 更新されたセッションを返す（イミュータブル）
  return {
    ...session,
    conversationHistory: [
      ...trimmedHistory,
      { role: 'assistant', content: aiText },
    ],
  }
}

// メッセージハンドラ（メインディスパッチャ）
async function handleMessage(
  ws: WebSocket,
  session: Session,
  data: ConversationRelayMessage
): Promise<Session> {
  switch (data.type) {
    case 'setup':
      return handleSetup(session, data)

    case 'prompt':
      return handlePrompt(ws, session, data)

    case 'interrupt':
      // 現状は特に処理なし（非ストリーミングのため）
      return session

    case 'dtmf':
      // デモでは未使用
      return session

    default:
      return session
  }
}

// WebSocket接続ハンドラ（エクスポート）
export function handleConversationRelay(ws: WebSocket): void {
  let session: Session = {
    callSid: '',
    conversationHistory: [],
    systemPrompt: '',
  }

  ws.on('message', async (rawData: WebSocket.RawData) => {
    try {
      const data: ConversationRelayMessage = JSON.parse(rawData.toString())
      session = await handleMessage(ws, session, data)
    } catch (error) {
      console.error('メッセージ処理エラー:', error)
    }
  })

  ws.on('close', () => {
    console.info(`WebSocket切断: callSid=${session.callSid}`)
  })

  ws.on('error', (error) => {
    console.error('WebSocketエラー:', error)
  })
}

