'use client'

import { useState, useEffect, useRef } from 'react'
import { SyncClient } from 'twilio-sync'

interface UseTwilioSyncReturn {
  syncClient: SyncClient | null
  isReady: boolean
}

export function useTwilioSync(): UseTwilioSyncReturn {
  const [syncClient, setSyncClient] = useState<SyncClient | null>(null)
  const [isReady, setIsReady] = useState(false)
  const clientRef = useRef<SyncClient | null>(null)

  useEffect(() => {
    async function initSync() {
      try {
        const response = await fetch('/api/sync-token')
        const result = await response.json()

        if (!result.success) {
          throw new Error(result.error || 'Syncトークン取得に失敗しました')
        }

        const client = new SyncClient(result.data.token)

        client.on('connectionStateChanged', (state: string) => {
          setIsReady(state === 'connected')
        })

        clientRef.current = client
        setSyncClient(client)
      } catch (error) {
        console.error('Sync Client初期化に失敗:', error)
      }
    }

    initSync()

    return () => {
      if (clientRef.current) {
        clientRef.current.shutdown()
        clientRef.current = null
      }
    }
  }, [])

  return { syncClient, isReady }
}

'use client'

import { useState, useCallback, useRef } from 'react'
import type { SyncClient } from 'twilio-sync'
import type { TranscriptMessage } from '@/types'

interface UseTranscriptReturn {
  messages: TranscriptMessage[]
  subscribeToCall: (callSid: string) => void
  clear: () => void
}

export function useTranscript(
  syncClient: SyncClient | null
): UseTranscriptReturn {
  const [messages, setMessages] = useState<TranscriptMessage[]>([])
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const listRef = useRef<any>(null)

  // 現在のサブスクリプションを解除
  const unsubscribe = useCallback(() => {
    if (listRef.current) {
      listRef.current.removeAllListeners()
      listRef.current.close()
      listRef.current = null
    }
  }, [])

  // Sync Listをサブスクライブ
  const subscribeToCall = useCallback(
    async (callSid: string) => {
      if (!syncClient) return

      // 既存のサブスクリプションを解除
      unsubscribe()
      setMessages([])

      try {
        const list = await syncClient.list(`transcript-${callSid}`)
        listRef.current = list

        // 既存アイテムの読み込み（再接続時対応）
        const page = await list.getItems({ from: 0, order: 'asc' })
        if (page.items.length > 0) {
          const existingMessages: TranscriptMessage[] = page.items.map(
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (item: any) => item.data as TranscriptMessage
          )
          setMessages(existingMessages)
        }

        // リアルタイム更新の監視
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        list.on('itemAdded', (event: any) => {
          const newMessage = event.item.data as TranscriptMessage
          setMessages((prev) => [...prev, newMessage])
        })
      } catch (error) {
        console.error('Sync Listサブスクリプションエラー:', error)
      }
    },
    [syncClient, unsubscribe]
  )

  // メッセージクリア
  const clear = useCallback(() => {
    unsubscribe()
    setMessages([])
  }, [unsubscribe])

  return { messages, subscribeToCall, clear }
}

'use client'

import { useEffect } from 'react'
import { useTwilioDevice } from '@/hooks/useTwilioDevice'
import { useTwilioSync } from '@/hooks/useTwilioSync'
import { useTranscript } from '@/hooks/useTranscript'
import { PromptEditor } from '@/components/PromptEditor'
import { PhoneControl } from '@/components/PhoneControl'
import { StatusIndicator } from '@/components/StatusIndicator'
import { TranscriptView } from '@/components/TranscriptView'

export default function Home() {
  const {
    status,
    callSid,
    connect,
    disconnect,
    toggleMute,
    isMuted,
  } = useTwilioDevice()

  const { syncClient, isReady: isSyncReady } = useTwilioSync()
  const { messages, subscribeToCall } = useTranscript(syncClient)

  // callSid取得後にSync Listをサブスクライブ
  useEffect(() => {
    if (callSid && isSyncReady) {
      subscribeToCall(callSid)
    }
  }, [callSid, isSyncReady, subscribeToCall])

  return (
    <main className="mx-auto max-w-2xl p-4">
      <h1 className="mb-6 text-2xl font-bold text-gray-900">
        AI電話応対デモ
      </h1>

      {/* プロンプト設定セクション */}
      <PromptEditor />

      {/* 通話セクション */}
      <section className="mt-8 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-800">
            ブラウザ電話
          </h2>
          <StatusIndicator status={status} />
        </div>

        <PhoneControl
          status={status}
          isMuted={isMuted}
          onConnect={connect}
          onDisconnect={disconnect}
          onToggleMute={toggleMute}
        />

        {/* LINE風文字起こし表示 */}
        <TranscriptView messages={messages} />
      </section>
    </main>
  )
}

