      const retryDelay = 1000

      for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
          const list = await syncClient.list(`transcript-${callSid}`)
          listRef.current = list

          // バッファ: リスナー登録前に届いたメッセージを一時保持
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const buffered: TranscriptMessage[] = []

          // リアルタイム更新の監視を先に登録（メッセージ欠落防止）
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          list.on('itemAdded', (event: any) => {
            const newMessage = event.item.data as TranscriptMessage
            buffered.push(newMessage)
            setMessages((prev) => [...prev, newMessage])
          })

          // 既存アイテムの読み込み（再接続時対応）
          const page = await list.getItems({ from: 0, order: 'asc' })
          if (page.items.length > 0) {
            const existingMessages: TranscriptMessage[] = page.items.map(
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              (item: any) => item.data as TranscriptMessage
            )
            // getItems中にitemAddedで既に追加されたメッセージと重複しないようマージ
            setMessages((prev) => {
              // prevにはitemAddedで追加されたメッセージが入っている可能性
              // existingMessagesを基準に、prevにしかないもの（itemAddedで後から来たもの）を追加
              const existingSet = new Set(
                existingMessages.map((m) => `${m.role}-${m.content}-${m.timestamp}`)
              )
              const newFromEvents = prev.filter(
                (m) => !existingSet.has(`${m.role}-${m.content}-${m.timestamp}`)
              )
              return [...existingMessages, ...newFromEvents]
            })
          }

          // サブスクリプション成功
