'use client'

import { useEffect } from 'react'
import { useTwilioDevice } from '@/hooks/useTwilioDevice'
import { useTwilioSync } from '@/hooks/useTwilioSync'
import { useTranscript } from '@/hooks/useTranscript'
import { PromptEditor } from '@/components/PromptEditor'
import { PhoneControl } from '@/components/PhoneControl'
import { StatusIndicator } from '@/components/StatusIndicator'
import { TranscriptView } from '@/components/TranscriptView'

export default function Home() {
  const {
    status,
    callSid,
    connect,
    disconnect,
    toggleMute,
    isMuted,
  } = useTwilioDevice()

  const { syncClient, isReady: isSyncReady } = useTwilioSync()
  const { messages, subscribeToCall } = useTranscript(syncClient)

  // callSid取得後にSync Listをサブスクライブ
  useEffect(() => {
    if (callSid && isSyncReady) {
      subscribeToCall(callSid)
    }
  }, [callSid, isSyncReady, subscribeToCall])

  return (
    <main className="mx-auto max-w-2xl p-4">
      <h1 className="mb-6 text-2xl font-bold text-gray-900">
        AI電話応対デモ
      </h1>

      {/* プロンプト設定セクション */}
      <PromptEditor />

      {/* 通話セクション */}
      <section className="mt-8 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-800">
            ブラウザ電話
          </h2>
          <StatusIndicator status={status} />
        </div>

        <PhoneControl
          status={status}
          isMuted={isMuted}
          onConnect={connect}
          onDisconnect={disconnect}
          onToggleMute={toggleMute}
        />

        {/* LINE風文字起こし表示 */}
        <TranscriptView messages={messages} />
      </section>
    </main>
  )
}

