import twilio from 'twilio'
import {
  getAccountSid,
  getApiKey,
  getApiSecret,
  getSyncServiceSid,
} from '@/lib/twilio'

const { AccessToken } = twilio.jwt
const { SyncGrant } = AccessToken

export async function GET() {
  try {
    const syncGrant = new SyncGrant({
      serviceSid: getSyncServiceSid(),
    })

    const token = new AccessToken(
      getAccountSid(),
      getApiKey(),
      getApiSecret(),
      { identity: 'browser-user' }
    )
    token.addGrant(syncGrant)

    return Response.json({
      success: true,
      data: { token: token.toJwt() },
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Syncトークン生成に失敗しました'
    return Response.json(
      { success: false, error: message },
      { status: 500 }
    )
  }
}

import type WebSocket from 'ws'
import { getSyncService } from './twilio'
import { getOpenaiClient, BASE_SYSTEM_PROMPT, FALLBACK_RESPONSES, trimHistory } from './openai'
import { getPrompt } from './prompt-store'
import type {
  Session,
  ConversationRelayMessage,
  SetupMessage,
  PromptMessage,
  ConversationMessage,
} from '../types'

// Sync Listにトランスクリプトアイテムを追加
async function addTranscriptItem(
  callSid: string,
  role: 'user' | 'assistant',
  content: string
): Promise<void> {
  try {
    await getSyncService()
      .syncLists(`transcript-${callSid}`)
      .syncListItems.create({
        data: {
          role,
          content,
          timestamp: new Date().toISOString(),
        },
      })
  } catch (error) {
    console.error('Sync書き込みエラー:', error)
  }
}

// setup メッセージ処理
async function handleSetup(
  session: Session,
  data: SetupMessage
): Promise<Session> {
  const userPrompt = getPrompt()
  const systemPrompt = `${BASE_SYSTEM_PROMPT}\n\n【応対内容】\n${userPrompt}`

  // Sync List作成（TTL: 1時間）
  try {
    await getSyncService().syncLists.create({
      uniqueName: `transcript-${data.callSid}`,
      ttl: 3600,
    })
  } catch (error) {
    console.error('Sync List作成エラー:', error)
  }

  return {
    callSid: data.callSid,
    conversationHistory: [],
    systemPrompt,
  }
}

// prompt メッセージ処理
async function handlePrompt(
  ws: WebSocket,
  session: Session,
  data: PromptMessage
): Promise<Session> {
  const userText = data.voicePrompt

  // ユーザー発話をSyncに書き込み
  await addTranscriptItem(session.callSid, 'user', userText)

  // 会話履歴を更新（イミュータブル）
  const updatedHistory: ConversationMessage[] = [
    ...session.conversationHistory,
    { role: 'user', content: userText },
  ]
  const trimmedHistory = trimHistory(updatedHistory)

  let aiText: string

  try {
    // OpenAI API呼び出し
    const response = await getOpenaiClient().chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        { role: 'system', content: session.systemPrompt },
        ...trimmedHistory,
      ],
      max_tokens: 150,
      temperature: 0.7,
      presence_penalty: 0.1,
    })

    aiText = response.choices[0]?.message?.content ?? FALLBACK_RESPONSES.general
  } catch (error) {
    console.error('OpenAI APIエラー:', error)

    // エラーの種類に応じたフォールバック
    if (error instanceof Error) {
      if (error.message.includes('429') || error.message.includes('rate')) {
        aiText = FALLBACK_RESPONSES.rateLimit
      } else if (error.message.includes('timeout') || error.message.includes('504')) {
        aiText = FALLBACK_RESPONSES.timeout
      } else {
        aiText = FALLBACK_RESPONSES.general
      }
    } else {
      aiText = FALLBACK_RESPONSES.general
    }
  }

  // AI応答をWebSocketに送信
  const responseMessage = JSON.stringify({
    type: 'text',
    token: aiText,
    last: true,
  })
  ws.send(responseMessage)

  // AI応答をSyncに書き込み
  await addTranscriptItem(session.callSid, 'assistant', aiText)

  // 更新されたセッションを返す（イミュータブル）
  return {
    ...session,
    conversationHistory: [
      ...trimmedHistory,
      { role: 'assistant', content: aiText },
    ],
  }
}

// メッセージハンドラ（メインディスパッチャ）
async function handleMessage(
  ws: WebSocket,
  session: Session,
  data: ConversationRelayMessage
): Promise<Session> {
  switch (data.type) {
    case 'setup':
      return handleSetup(session, data)

    case 'prompt':
      return handlePrompt(ws, session, data)

    case 'interrupt':
      // 現状は特に処理なし（非ストリーミングのため）
      return session

    case 'dtmf':
      // デモでは未使用
      return session

    default:
      return session
  }
}

// WebSocket接続ハンドラ（エクスポート）
export function handleConversationRelay(ws: WebSocket): void {
  let session: Session = {
    callSid: '',
    conversationHistory: [],
    systemPrompt: '',
  }

  ws.on('message', async (rawData: WebSocket.RawData) => {
    try {
      const data: ConversationRelayMessage = JSON.parse(rawData.toString())
      session = await handleMessage(ws, session, data)
    } catch (error) {
      console.error('メッセージ処理エラー:', error)
    }
  })

  ws.on('close', () => {
    console.info(`WebSocket切断: callSid=${session.callSid}`)
  })

  ws.on('error', (error) => {
    console.error('WebSocketエラー:', error)
  })
}

import OpenAI from 'openai'
import type { ConversationMessage } from '@/types'

// OpenAIクライアント（遅延初期化）
let _openaiClient: OpenAI | null = null

export function getOpenaiClient(): OpenAI {
  if (!_openaiClient) {
    const apiKey = process.env.OPENAI_API_KEY
    if (!apiKey) {
      throw new Error('環境変数 OPENAI_API_KEY が設定されていません')
    }
    _openaiClient = new OpenAI({ apiKey })
  }
  return _openaiClient
}

// ベースシステムプロンプト（固定部分）
export const BASE_SYSTEM_PROMPT = `あなたは電話応対AIアシスタントです。以下のルールに従って応答してください。

【応答ルール】
- 1回の応答は1〜2文（50文字以内目安）で簡潔に答える
- 書き言葉ではなく、話し言葉（口語）で返答する
- 丁寧な敬語（です/ます調）を使用する
- 「はい」「承知しました」「かしこまりました」など適切に相槌を入れる
- 重要な情報（日時、人数、名前など）は必ず復唱して確認する
- 一度に複数の質問をしない。1つずつ確認する
- 電話番号、住所など長い情報は区切って伝える
- わからないことは正直に「確認いたします」と伝える

【禁止事項】
- マークダウン記法やリスト形式で話さない
- URLやメールアドレスを読み上げない
- 長い説明を一度に話さない`

// エラー時のフォールバック応答
export const FALLBACK_RESPONSES = {
  timeout: 'すみません、少しお時間いただいてもよろしいでしょうか。',
  rateLimit: '申し訳ございません、ただいま混み合っております。少々お待ちください。',
  general: '申し訳ございません、うまく聞き取れませんでした。もう一度おっしゃっていただけますか？',
} as const

// 会話履歴のトリミング（最大20往復 = 40メッセージ）
export function trimHistory(
  history: readonly ConversationMessage[],
  maxPairs: number = 20
): ConversationMessage[] {
  const maxMessages = maxPairs * 2
  if (history.length > maxMessages) {
    return history.slice(-maxMessages)
  }
  return [...history]
}

# Twilio Sync仕様

[← CLAUDE.mdに戻る](../CLAUDE.md)

## 概要

Twilio Syncを使用して、サーバーサイド（WebSocketハンドラ）で生成される文字起こしデータをブラウザにリアルタイム同期する。

## データ構造

### Sync List: `transcript-{callSid}`

通話ごとにSync Listを作成し、発話データを順次追加する。

**List名パターン**: `transcript-CAxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx`

**各アイテムのデータ形式:**
```json
{
  "role": "user",
  "content": "明日の18時に2名で予約したいのですが",
  "timestamp": "2024-01-15T09:32:15.000Z"
}
```

| フィールド | 型 | 説明 |
|---|---|---|
| `role` | `"user"` \| `"assistant"` | 発話者。ユーザーまたはAI |
| `content` | `string` | 発話テキスト |
| `timestamp` | `string` (ISO 8601) | 発話時刻 |

## サーバーサイド（書き込み）

WebSocketハンドラ内で、Twilio REST APIを使用してSync Listにアイテムを追加する。

```typescript
import twilio from 'twilio';

const client = twilio(accountSid, authToken);
const syncService = client.sync.v1.services(syncServiceSid);

// Sync Listの作成（通話開始時）
async function createTranscriptList(callSid: string) {
  await syncService.syncLists.create({
    uniqueName: `transcript-${callSid}`,
    ttl: 3600,  // 1時間後に自動削除（デモ用途）
  });
}

// アイテム追加（発話ごと）
async function addTranscriptItem(
  callSid: string,
  role: 'user' | 'assistant',
  content: string
) {
  await syncService
    .syncLists(`transcript-${callSid}`)
    .syncListItems.create({
      data: {
        role,
        content,
        timestamp: new Date().toISOString(),
      },
    });
}
```

## フロントエンド（読み取り・リアルタイム同期）

### Syncトークン生成 (`/api/sync-token/route.ts`)

```typescript
const syncGrant = new SyncGrant({
  serviceSid: process.env.TWILIO_SYNC_SERVICE_SID,
});

const token = new AccessToken(
  accountSid, apiKey, apiSecret, { identity: 'browser-user' }
);
token.addGrant(syncGrant);
```

### Sync Clientの初期化と購読

```typescript
import { SyncClient } from 'twilio-sync';

// 初期化
const syncClient = new SyncClient(syncToken);

// Sync Listをサブスクライブ
async function subscribeToTranscript(callSid: string) {
  const list = await syncClient.list(`transcript-${callSid}`);

  // 既存アイテムの読み込み（再接続時）
  const page = await list.getItems();
  page.items.forEach(item => {
    addMessage(item.data);
  });

  // リアルタイム更新の監視
  list.on('itemAdded', (event) => {
    addMessage(event.item.data);
  });
}
```

## callSidの受け渡し

通話開始時にフロントエンドがcallSidを取得し、Sync Listのサブスクリプションに使用する。

```
1. device.connect() で通話開始
2. call.on('accept', () => { ... }) で接続確立を検知
3. call.parameters.CallSid でcallSidを取得
4. subscribeToTranscript(callSid) でSync Listを購読
```

> **注意**: Voice SDK JS v2では、`call.parameters.CallSid` でサーバーサイドのCallSidが取得できる。

## ライフサイクル

```
通話開始 → Sync List作成 (TTL: 1時間)
  ↓
会話中 → アイテム追加 (ユーザー発話 / AI応答)
  ↓
通話終了 → （Listは残る、TTLで自動削除）
  ↓
1時間後 → Sync Listが自動削除
```

## トラブルシューティング

| 問題 | 原因 | 対処 |
|---|---|---|
| Sync Listが見つからない | callSidの不一致 | サーバー・クライアントで同じcallSidを使用しているか確認 |
| itemAddedが発火しない | トークンにSync Grantがない | `/api/sync-token` のGrant設定を確認 |
| 同期が遅い | Sync Service SIDが違う | 環境変数 `TWILIO_SYNC_SERVICE_SID` を確認 |
| 権限エラー | List ACL設定 | Sync ServiceのACL設定を確認 |

export async function POST() {
  try {
    const appUrl = process.env.NEXT_PUBLIC_APP_URL
    if (!appUrl) {
      throw new Error('環境変数 NEXT_PUBLIC_APP_URL が設定されていません')
    }

    // https://xxx → xxx のホスト部分を抽出してwss URLを構築
    const host = appUrl.replace(/^https?:\/\//, '')
    const wsUrl = `wss://${host}/ws/conversation-relay`

    const twiml = `<?xml version="1.0" encoding="UTF-8"?>
