} from '@/lib/twilio'

const { AccessToken } = twilio.jwt
const { VoiceGrant } = AccessToken

export async function GET() {
  try {
    const voiceGrant = new VoiceGrant({
      outgoingApplicationSid: getTwimlAppSid(),
