'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { Device, Call } from '@twilio/voice-sdk'
import type { CallStatus } from '@/types'

interface UseTwilioDeviceReturn {
  device: Device | null
  call: Call | null
  status: CallStatus
  callSid: string | null
  connect: () => Promise<void>
  disconnect: () => void
  toggleMute: () => void
  isMuted: boolean
}

export function useTwilioDevice(): UseTwilioDeviceReturn {
  const [device, setDevice] = useState<Device | null>(null)
  const [call, setCall] = useState<Call | null>(null)
  const [status, setStatus] = useState<CallStatus>('idle')
  const [callSid, setCallSid] = useState<string | null>(null)
  const [isMuted, setIsMuted] = useState(false)
  const deviceRef = useRef<Device | null>(null)

  // Device初期化
  useEffect(() => {
    async function initDevice() {
      try {
        const response = await fetch('/api/token')
        const result = await response.json()

        if (!result.success) {
          throw new Error(result.error || 'トークン取得に失敗しました')
        }

        const newDevice = new Device(result.data.token, {
          edge: ['tokyo', 'singapore'],
        })

        newDevice.on('registered', () => {
          setStatus('idle')
        })

        newDevice.on('error', (error) => {
          console.error('Device error:', error)
          setStatus('error')
        })

        await newDevice.register()
        deviceRef.current = newDevice
        setDevice(newDevice)
      } catch (error) {
        console.error('Device初期化に失敗:', error)
        setStatus('error')
      }
    }

    initDevice()

    return () => {
      if (deviceRef.current) {
        deviceRef.current.destroy()
        deviceRef.current = null
      }
    }
  }, [])

  // 通話開始
  const connect = useCallback(async () => {
    if (!device || status === 'connecting' || status === 'connected') {
      return
    }

    try {
      setStatus('connecting')
      setIsMuted(false)

      const newCall = await device.connect({
        params: { To: 'conversation-relay' },
      })

      newCall.on('accept', () => {
        setStatus('connected')
        // CallSidを取得
        const sid = newCall.parameters?.CallSid ?? null
        setCallSid(sid)
      })

      newCall.on('disconnect', () => {
        setStatus('disconnected')
        setCall(null)
        setIsMuted(false)
      })

      newCall.on('error', (error) => {
        console.error('Call error:', error)
        setStatus('error')
        setCall(null)
      })

      newCall.on('cancel', () => {
        setStatus('idle')
        setCall(null)
      })

      setCall(newCall)
    } catch (error) {
      console.error('通話接続に失敗:', error)
      setStatus('error')
    }
  }, [device, status])

  // 通話切断
  const disconnect = useCallback(() => {
    if (!call) return
    call.disconnect()
  }, [call])

  // ミュートトグル
  const toggleMute = useCallback(() => {
    if (!call) return
    const newMuted = !isMuted
    call.mute(newMuted)
    setIsMuted(newMuted)
  }, [call, isMuted])

  return {
    device,
    call,
    status,
    callSid,
    connect,
    disconnect,
    toggleMute,
    isMuted,
  }
}

