export async function POST() {
  try {
    const appUrl = process.env.NEXT_PUBLIC_APP_URL
    if (!appUrl) {
      throw new Error('環境変数 NEXT_PUBLIC_APP_URL が設定されていません')
    }

    // https://xxx → xxx のホスト部分を抽出してwss URLを構築
    const host = appUrl.replace(/^https?:\/\//, '')
    const wsUrl = `wss://${host}/ws/conversation-relay`

    const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Connect>
    <ConversationRelay
      url="${wsUrl}"
      voice="ja-JP-Neural2-B"
      language="ja-JP"
      transcriptionProvider="google"
      speechModel="telephony"
      welcomeGreeting="お電話ありがとうございます。ご用件をお話しください。"
      dtmfDetection="true"
      interruptible="true"
      interruptByDtmf="false"
    />
  </Connect>
</Response>`

    return new Response(twiml, {
      status: 200,
      headers: { 'Content-Type': 'text/xml' },
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'TwiML生成に失敗しました'
    return Response.json(
      { success: false, error: message },
      { status: 500 }
    )
  }
}

